const n='# 📘 第3课：结构体与类的应用\n\n> **课程定位**：实战应用课 —— 通过项目驱动掌握结构体和类\n\n---\n\n## 一、学习目标\n\n通过本课学习，你将能够：\n\n1. ✅ 熟练使用结构体组织数据\n2. ✅ 理解类的基本概念（封装）\n3. ✅ 通过实际案例掌握结构体/类的应用场景\n4. ✅ 能够独立设计和使用自定义数据类型\n\n---\n\n## 二、结构体回顾\n\n### 2.1 为什么需要结构体？\n\n**问题场景**：管理学生信息（学号、姓名、成绩）\n\n```cpp\n// 不好的方式：多个数组\nint ids[100];\nstring names[100];\nint scores[100];\n// 问题：数据分散，不好管理\n\n// 好的方式：结构体\nstruct Student {\n    int id;\n    string name;\n    int score;\n};\nStudent students[100];  // 一个数组搞定！\n```\n\n### 2.2 结构体基础语法\n\n```cpp\n// 定义结构体\nstruct Point {\n    int x;\n    int y;\n};\n\n// 使用结构体\nPoint p1;           // 声明\np1.x = 10;          // 访问成员\np1.y = 20;\n\nPoint p2 = {30, 40};  // 初始化\n```\n\n---\n\n## 三、类的基本概念\n\n### 3.1 从结构体到类\n\n**类 = 数据 + 操作数据的函数**\n\n```cpp\n// 结构体版本\nstruct Rectangle {\n    int width;\n    int height;\n};\n\nint getArea(Rectangle r) {\n    return r.width * r.height;\n}\n\n// 类版本：把函数放进来\nclass Rectangle {\npublic:\n    int width;\n    int height;\n\n    int getArea() {\n        return width * height;\n    }\n};\n```\n\n### 3.2 类的基本结构\n\n```cpp\nclass 类名 {\npublic:      // 公有成员：外部可访问\n    // 成员变量\n    // 成员函数\n\nprivate:     // 私有成员：仅类内部可访问\n    // 成员变量\n    // 成员函数\n};\n```\n\n### 3.3 构造函数\n\n**构造函数**：创建对象时自动调用，用于初始化\n\n```cpp\nclass Student {\npublic:\n    string name;\n    int score;\n\n    // 构造函数（与类名相同，无返回值）\n    Student() {\n        name = "";\n        score = 0;\n    }\n\n    // 带参数的构造函数\n    Student(string n, int s) {\n        name = n;\n        score = s;\n    }\n\n    void print() {\n        cout << name << ": " << score << endl;\n    }\n};\n\nint main() {\n    Student s1;                    // 调用无参构造\n    Student s2("张三", 90);        // 调用带参构造\n    s2.print();                    // 输出: 张三: 90\n    return 0;\n}\n```\n\n### 3.4 struct vs class\n\n| 特性         | struct       | class        |\n| ------------ | ------------ | ------------ |\n| 默认访问权限 | public       | private      |\n| 常用场景     | 简单数据组合 | 复杂对象封装 |\n| C 兼容性     | 兼容         | 不兼容       |\n\n**实际建议**：简单数据用 struct，需要封装时用 class\n\n---\n\n## 四、📝 实战项目一：学生成绩管理系统\n\n### 题目描述\n\n设计一个学生成绩管理系统，实现以下功能：\n\n1. 录入学生信息\n2. 按成绩排序\n3. 查找学生\n4. 统计及格率\n\n### 代码实现\n\n```cpp\n#include <iostream>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nclass Student {\npublic:\n    string name;\n    int score;\n\n    Student() : name(""), score(0) {}\n    Student(string n, int s) : name(n), score(s) {}\n\n    void input() {\n        cin >> name >> score;\n    }\n\n    void print() {\n        cout << name << " " << score << endl;\n    }\n\n    bool isPassed() {\n        return score >= 60;\n    }\n};\n\nclass ScoreSystem {\nprivate:\n    Student students[100];\n    int count;\n\npublic:\n    ScoreSystem() : count(0) {}\n\n    // 添加学生\n    void addStudent(string name, int score) {\n        students[count++] = Student(name, score);\n    }\n\n    // 输入多个学生\n    void inputStudents(int n) {\n        count = n;\n        for (int i = 0; i < n; i++) {\n            students[i].input();\n        }\n    }\n\n    // 按成绩降序排序\n    void sortByScore() {\n        for (int i = 0; i < count - 1; i++) {\n            for (int j = 0; j < count - 1 - i; j++) {\n                if (students[j].score < students[j + 1].score) {\n                    swap(students[j], students[j + 1]);\n                }\n            }\n        }\n    }\n\n    // 查找学生\n    Student* findStudent(string name) {\n        for (int i = 0; i < count; i++) {\n            if (students[i].name == name) {\n                return &students[i];\n            }\n        }\n        return nullptr;\n    }\n\n    // 计算及格率\n    double getPassRate() {\n        int passed = 0;\n        for (int i = 0; i < count; i++) {\n            if (students[i].isPassed()) passed++;\n        }\n        return count > 0 ? (double)passed / count * 100 : 0;\n    }\n\n    // 打印所有学生\n    void printAll() {\n        for (int i = 0; i < count; i++) {\n            students[i].print();\n        }\n    }\n\n    // 获取最高分\n    Student getTop() {\n        int maxIdx = 0;\n        for (int i = 1; i < count; i++) {\n            if (students[i].score > students[maxIdx].score) {\n                maxIdx = i;\n            }\n        }\n        return students[maxIdx];\n    }\n};\n\nint main() {\n    ScoreSystem sys;\n\n    cout << "请输入学生人数: ";\n    int n;\n    cin >> n;\n\n    cout << "请输入每个学生的姓名和成绩:" << endl;\n    sys.inputStudents(n);\n\n    cout << "\\n按成绩排序后:" << endl;\n    sys.sortByScore();\n    sys.printAll();\n\n    cout << "\\n及格率: " << sys.getPassRate() << "%" << endl;\n    cout << "最高分: ";\n    sys.getTop().print();\n\n    return 0;\n}\n```\n\n---\n\n## 五、📝 实战项目二：银行账户系统\n\n### 题目描述\n\n设计银行账户类，支持：存款、取款、查询余额、转账\n\n### 代码实现\n\n```cpp\n#include <iostream>\n#include <string>\nusing namespace std;\n\nclass BankAccount {\nprivate:\n    string owner;      // 户主\n    double balance;    // 余额\n    string accountId;  // 账号\n\npublic:\n    // 构造函数\n    BankAccount(string id, string name, double initial = 0) {\n        accountId = id;\n        owner = name;\n        balance = initial;\n    }\n\n    // 存款\n    void deposit(double amount) {\n        if (amount > 0) {\n            balance += amount;\n            cout << "存款成功! 当前余额: " << balance << endl;\n        } else {\n            cout << "存款金额必须大于0!" << endl;\n        }\n    }\n\n    // 取款\n    bool withdraw(double amount) {\n        if (amount > balance) {\n            cout << "余额不足!" << endl;\n            return false;\n        }\n        if (amount <= 0) {\n            cout << "取款金额必须大于0!" << endl;\n            return false;\n        }\n        balance -= amount;\n        cout << "取款成功! 当前余额: " << balance << endl;\n        return true;\n    }\n\n    // 查询余额\n    double getBalance() {\n        return balance;\n    }\n\n    // 转账\n    bool transfer(BankAccount &target, double amount) {\n        if (withdraw(amount)) {\n            target.deposit(amount);\n            cout << "转账成功!" << endl;\n            return true;\n        }\n        return false;\n    }\n\n    // 显示账户信息\n    void showInfo() {\n        cout << "账号: " << accountId << endl;\n        cout << "户主: " << owner << endl;\n        cout << "余额: " << balance << endl;\n    }\n};\n\nint main() {\n    BankAccount acc1("001", "张三", 1000);\n    BankAccount acc2("002", "李四", 500);\n\n    cout << "=== 初始状态 ===" << endl;\n    acc1.showInfo();\n    cout << endl;\n    acc2.showInfo();\n\n    cout << "\\n=== 张三存款200 ===" << endl;\n    acc1.deposit(200);\n\n    cout << "\\n=== 张三取款500 ===" << endl;\n    acc1.withdraw(500);\n\n    cout << "\\n=== 张三转账300给李四 ===" << endl;\n    acc1.transfer(acc2, 300);\n\n    cout << "\\n=== 最终状态 ===" << endl;\n    acc1.showInfo();\n    cout << endl;\n    acc2.showInfo();\n\n    return 0;\n}\n```\n\n---\n\n## 六、数据结构入门：栈与队列 (Stack & Queue)\n\n在学习了类和对象之后，我们可以利用它们来封装一些经典的数据结构。\n\n### 6.1 栈 (Stack) - "后进先出"\n\n**概念**：栈就像一个羽毛球筒，最先放进去的球最后才能拿出来。\n**特点**：后进先出 (LIFO - Last In First Out)\n**常用操作**：\n\n- `push`: 入栈（放入顶部）\n- `pop`: 出栈（移除顶部）\n- `top`: 查看顶部元素\n- `empty`: 判断是否为空\n\n**实战任务**：使用 `vector` 实现一个整数栈 `MyStack`\n\n```cpp\n#include <iostream>\n#include <vector>\nusing namespace std;\n\nclass MyStack {\nprivate:\n    vector<int> data;\n\npublic:\n    // 入栈\n    void push(int val) {\n        data.push_back(val);\n    }\n\n    // 出栈\n    void pop() {\n        if (!empty()) {\n            data.pop_back();\n        }\n    }\n\n    // 获取栈顶元素\n    int top() {\n        if (!empty()) {\n            return data.back();\n        }\n        throw runtime_error("Stack is empty");\n    }\n\n    // 判断为空\n    bool empty() {\n        return data.empty();\n    }\n\n    // 获取大小\n    int size() {\n        return data.size();\n    }\n};\n\nint main() {\n    MyStack s;\n    s.push(10);\n    s.push(20);\n    s.push(30);\n\n    cout << "栈顶元素: " << s.top() << endl; // 30\n    s.pop();\n    cout << "弹出后栈顶: " << s.top() << endl; // 20\n\n    return 0;\n}\n```\n\n### 6.2 队列 (Queue) - "先进先出"\n\n**概念**：队列就像排队买票，先来的人先买。\n**特点**：先进先出 (FIFO - First In First Out)\n**常用操作**：\n\n- `push`: 入队（放入队尾）\n- `pop`: 出队（移除队头）\n- `front`: 查看队头元素\n- `empty`: 判断是否为空\n\n**实战任务**：使用两个 `vector` 实现一个队列 `MyQueue`\n\n**思考**：为什么要用两个 vector？\n\n- `vector` 在头部删除元素 (`erase(begin())`) 效率较低，因为后面的元素都要向前移动。\n- 我们可以用两个栈（`inStack` 和 `outStack`）来模拟队列，保证所有操作依然高效。\n\n**实现逻辑**：\n\n1. **入队**：直接 push 进入 `inStack`。\n2. **出队/查看队头**：\n   - 如果 `outStack` 不为空，直接从 `outStack` 顶部取。\n   - 如果 `outStack` 为空，将 `inStack` 所有元素倒序倒入 `outStack`，然后再取。\n\n```cpp\n#include <iostream>\n#include <vector>\nusing namespace std;\n\nclass MyQueue {\nprivate:\n    vector<int> inStack;   // 负责进\n    vector<int> outStack;  // 负责出\n\n    // 辅助函数：将 inStack 数据转移到 outStack\n    void move() {\n        if (outStack.empty()) {\n            while (!inStack.empty()) {\n                outStack.push_back(inStack.back());\n                inStack.pop_back();\n            }\n        }\n    }\n\npublic:\n    // 入队\n    void push(int x) {\n        inStack.push_back(x);\n    }\n\n    // 出队\n    void pop() {\n        move();\n        if (!outStack.empty()) {\n            outStack.pop_back();\n        }\n    }\n\n    // 获取队头元素\n    int front() {\n        move();\n        if (!outStack.empty()) {\n            return outStack.back();\n        }\n        throw runtime_error("Queue is empty");\n    }\n\n    // 判断为空\n    bool empty() {\n        return inStack.empty() && outStack.empty();\n    }\n};\n\nint main() {\n    MyQueue q;\n    q.push(1);\n    q.push(2);\n    q.push(3);\n\n    cout << "队头元素: " << q.front() << endl; // 1\n    q.pop();\n    cout << "出队一次后队头: " << q.front() << endl; // 2\n\n    q.push(4);\n    cout << "加入4后队头: " << q.front() << endl; // 2 (依然是2)\n\n    return 0;\n}\n```\n\n---\n\n---\n\n## 七、本课小结\n\n### 设计思想\n\n1. **数据抽象**：将现实事物抽象为结构体/类\n2. **封装**：数据和操作放在一起\n3. **模块化**：分解复杂问题\n\n### 应用场景对比\n\n| 场景         | 推荐使用         | 原因       |\n| ------------ | ---------------- | ---------- |\n| 简单数据组合 | struct           | 简洁明了   |\n| 需要隐藏数据 | class + private  | 防止误操作 |\n| 需要初始化   | class + 构造函数 | 自动初始化 |\n| 复杂系统     | class            | 方便扩展   |\n\n### 编程技巧\n\n- ✅ 先设计数据结构，再写操作函数\n- ✅ 构造函数做好初始化\n- ✅ 成员函数保持简单，一个函数做一件事\n- ✅ 用 private 保护关键数据\n\n---\n\n## 八、课后练习\n\n1. 使用 `MyStack` 实现字符串反转（输入 "abc"，输出 "cba"）。\n2. 在 `MyQueue` 类中增加 `size()` 函数，返回队列中的元素个数。\n3. 扩展：尝试使用前面写的 `Student` 类，建立一个 `MyStack<Student>`（存储结构体的栈，了解即可）。\n4. (挑战) 有效的括号：使用栈判断 `{[()]}` 这样的字符串是否合法。\n\n---\n\n**下节预告**：第4课 - 高精度加法，挑战超大整数运算！\n';export{n as default};
